template<class A, class B>
struct pair
{
  A first;
  B second;

  pair(const A &a, const B &b) : first(a), second(b) {}
};

typedef const script_library_class::function *value_type;

struct node
{
  int color;
  node *parent;
  node *left;
  node *right;
  value_type value;
};

struct iterator
{
  node *current;

  iterator(node *x) : current(x) {}

  iterator &operator--()
  {
    if (current->color == 0 && current->parent->parent == current)
      current = current->right;
    else if (current->left != 0)
    {
      node *y = current->left;
      while (y->right != 0)
        y = y->right;
      current = y;
    }
    else
    {
      node *y = current->parent;
      while (current == y->left)
      {
        current = y;
        y = y->parent;
      }
      current = y;
    }
    return *this;
  }
};

